bash -lc cat > /mnt/data/flatten_meta_procedure_runtime.js <<'JS'
'use strict';
const fs = require('fs');
const crypto = require('crypto');
const inputPath = '/mnt/data/731942_source_retrieved.json';
const outputPath = '/mnt/data/731942_meta_procedure_flattened_return.json';
const sourceText = fs.readFileSync(inputPath, 'utf8');
const source = JSON.parse(sourceText);
const projection = [];
const factLedger = [];
const metrics = {
  source_terminal_values: 0,
  source_object_containers: 0,
  source_array_containers: 0,
  source_object_properties: 0,
  source_array_elements: 0,
  root_container_atoms: 0,
  keyed_object_literal_atoms: 0,
  keyed_array_literal_atoms: 0,
  anonymous_empty_container_atoms: 0,
  terminal_property_atoms: 0,
  primitive_array_member_atoms: 0
};
const hasOwn = (o,k) => Object.prototype.hasOwnProperty.call(o,k);
const isObject = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const cloneJson = v => JSON.parse(JSON.stringify(v));

// A route identifies provenance only while running: no paths or indexes are stored inside the emitted atoms.
function atomAt(route, payload) {
  let atom = cloneJson(payload);
  for (let i = route.length - 1; i >= 0; i--) {
    const step = route[i];
    if (step.type === 'key') {
      const box = Object.create(null);
      box[step.value] = atom;
      atom = box;
    } else {
      atom = [atom];
    }
  }
  return atom;
}
function emit(route, value, type) {
  const atom = atomAt(route, value);
  const index = projection.length;
  projection.push(atom);
  factLedger.push({index, route: route.map(x => ({type:x.type, value:x.value})), type});
}
function visit(value, route, relation) {
  if (isObject(value)) {
    metrics.source_object_containers++;
    if (relation === 'root') {
      emit([], {}, 'root_object'); metrics.root_container_atoms++;
    } else if (relation === 'keyed') {
      emit(route, {}, 'keyed_object'); metrics.keyed_object_literal_atoms++;
    } else if (Object.keys(value).length === 0) {
      emit(route, {}, 'empty_anonymous_object'); metrics.anonymous_empty_container_atoms++;
    }
    for (const key of Object.keys(value)) {
      metrics.source_object_properties++;
      const child = value[key];
      const childRoute = route.concat({type:'key',value:key});
      if (isObject(child) || Array.isArray(child)) {
        visit(child, childRoute, 'keyed');
      } else {
        metrics.source_terminal_values++;
        metrics.terminal_property_atoms++;
        emit(childRoute, child, 'terminal_property');
      }
    }
  } else if (Array.isArray(value)) {
    metrics.source_array_containers++;
    if (relation === 'root') {
      emit([], [], 'root_array'); metrics.root_container_atoms++;
    } else if (relation === 'keyed') {
