#!/usr/bin/env node
'use strict';

const fs = require('node:fs');
const { randomInt } = require('node:crypto');

/**
 * Canonical atomic nested-JSON projection, following
 * GeminiSupervisor/README.md, "Canonical JSON flattening and shuffle representation".
 *
 * Every emitted top-level element adds exactly one fact. Ancestors are
 * represented by the original nested JSON containers, never path metadata.
 * Object/array roots only: the README does not specify scalar roots.
 */
function flattenJson(value) {
  if (value === null || typeof value !== 'object') {
    throw new TypeError('The documented projection requires an object or array JSON root.');
  }

  const atoms = [];
  const emit = (atom) => atoms.push(atom);
  const identity = (x) => x;

  // `wrap` embeds one payload under all original ancestor containers.
  // All array wrappers intentionally contain exactly one child.
  function visit(node, wrap, keyed) {
    if (Array.isArray(node)) {
      if (keyed || wrap === identity) {
        emit(wrap([])); // keyed array literal, or bare root-array literal
      } else if (node.length === 0) {
        emit(wrap([])); // anonymous empty array that would vanish
      }
      for (const member of node) {
        visit(member, (child) => wrap([child]), false);
      }
      return;
    }

    if (node !== null && typeof node === 'object') {
      if (keyed || wrap === identity) {
        emit(wrap({})); // keyed object literal, or bare root-object literal
      } else if (Object.keys(node).length === 0) {
        emit(wrap({})); // anonymous empty object that would vanish
      }
      for (const [key, child] of Object.entries(node)) {
        // Computed property notation preserves literal keys, including __proto__.
        visit(child, (v) => wrap({ [key]: v }), true);
      }
      return;
    }

    // A scalar is one terminal property or one array-member fact.
    emit(wrap(node));
  }

  visit(value, identity, false);
  return atoms;
}

/** Optional shuffle: affect ONLY the outermost projection array. */
function shuffleOuterAtoms(atoms) {
  const copy = atoms.slice();
  for (let i = copy.length - 1; i > 0; i--) {
    const j = randomInt(i + 1);
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy;
}

if (require.main === module) {
  const args = process.argv.slice(2);
  const shuffle = args.includes('--shuffle');
  const paths = args.filter(arg => arg !== '--shuffle');
  if (paths.length !== 1) {
    process.stderr.write('Usage: node flatten-json.js <input.json> [--shuffle]\n');
    process.exit(2);
  }
  try {
    const source = JSON.parse(fs.readFileSync(paths[0], 'utf8'));
    const atoms = flattenJson(source);
    const output = shuffle ? shuffleOuterAtoms(atoms) : atoms;
    process.stdout.write(JSON.stringify(output) + '\n');
  } catch (e) {
    process.stderr.write(`${e.name}: ${e.message}\n`);
    process.exit(1);
  }
}

module.exports = { flattenJson, shuffleOuterAtoms };
