function isScalar(v){return v === null || (typeof v !== 'object');}
function recName(o) {
  if (o && typeof o === 'object' && !Array.isArray(o)) {
    for (const k of ['name','term','title','procedure_name','label']) {
      if(typeof o[k] === 'string' && o[k].length < 90) return o[k];
    }
