  const where='Within '+context+', ';
  if(v===null) return prefix+where+memberText+' is explicitly null (no non-null value is supplied).';
  if(typeof v==='boolean'){
    if(field==='required_by_default') return prefix+where+(v?'the associated operation is mandatory by default.':'the associated operation is not mandatory by default.');
    return prefix+where+memberText+' is '+(v?'enabled or affirmed (true).':'disabled or negated (false).');
  }
  if(typeof v==='number') return prefix+where+memberText+' specifies numeric value '+String(v)+'.';
  const s=trimText(v);
  if(s==='') return prefix+where+memberText+' is an explicitly empty string.';
  if(field==='response_type') return 'The document identifies its type as '+quote(s)+'.';
  if(field==='status') return prefix+where+'the declared status is '+quote(s)+'; this is a source assertion, not independent execution evidence.';
  if(field==='result' || field==='evaluation') return prefix+where+memberText+' is '+quote(s)+'; this records what the source reports, not an independent verification.';
  if(field==='classification') return prefix+where+'the interpretation is classified as '+quote(s)+'.';
  if(field==='term') return prefix+where+'the concept being defined is '+quote(s)+'.';
  if(field==='definition') return prefix+where+'the concept is defined as follows: '+s;
  if(field==='name') return prefix+where+'the named concept is '+quote(s)+'.';
  if(field.endsWith('_id') || field==='reference' || field==='source_reference') return prefix+where+memberText+' identifies '+quote(s)+'.';
  if(field==='version') return prefix+where+'the declared version is '+quote(s)+'.';
