function defineContainer(meta){
 const section=meta.path[0];
 if(meta.kind==='root_object')return 'The canonical MetaProcedure is a top-level JSON object containing its governing sections and return schema.';
 if(meta.kind==='root_array')return 'The supplied JSON root is an array of elements to be interpreted in source order.';
 const key=meta.path[meta.path.length-1];
 const isMember=typeof key==='number';
 const field=isMember?meta.path[meta.path.length-2]:key;
 const context=ownerContext(meta.path);
 const role=fieldRoles[field]||('the '+human(field));
 const container=meta.valueIsArray?'an array':'an object';
 if(meta.kind==='anonymous_empty')return 'Within '+context+', this array member is an explicitly empty '+(meta.valueIsArray?'array':'object')+' whose presence must be retained.';
 if(meta.kind==='keyed_array')return 'Within '+context+', '+role+' is an array-valued field containing an ordered collection; this atom declares its container type independently of its members.';
 if(meta.kind==='keyed_object')return 'Within '+context+', '+role+' is an object-valued field containing named subordinate facts; this atom declares its container type independently of its properties.';
 return 'Within '+context+', the source declares '+container+'.';
