function atomAtRoute(route, fact){
 let atom=fact;
 for(let i=route.length-1;i>=0;i--){
  const e=route[i];atom=e.kind==='member'?[atom]:{[e.key]:atom};
 }
 return atom;
}
const records=[];
function emit(fact,p,route,kind){
