 if(!Number.isInteger(i)||i<0||i>=flattened.length) throw new RangeError(`Invalid projection index: ${i}`);
 return {[String(i)]:records[i].definition};
}

const indexArray=Array.from({length:flattened.length},(_,i)=>i);
for(let i=0;i<indexArray.length;i++)indexArray[i]=defineAtIndex(i);
