      "maximum_turn_interval": 3,
      "minimum_regurgitation_fraction": 0.1,
      "minimum_regurgitation_percent": 10,
      "rule": "No fewer than once every 3 AI-NLE turns, read the full current text of every document assigned to Schedule 3 and regurgitate at least 10 percent of the values and definitions from each document.",
      "first_due_turn": 3,
      "subsequent_due_rule": "A new qualifying reading exercise must occur no later than 3 turns after the previous qualifying Schedule 3 reading exercise.",
      "per_document_requirement": true,
      "minimum_units_formula": "ceil(total_values_and_definitions_in_document * 0.10)"
    },
    "schedule_5": {
      "maximum_turn_interval": 5,
      "minimum_regurgitation_fraction": 0.25,
      "minimum_regurgitation_percent": 25,
      "rule": "No fewer than once every 5 AI-NLE turns, read the full current text of every document assigned to Schedule 5 and regurgitate at least 25 percent of the values and definitions from each document.",
      "first_due_turn": 5,
      "subsequent_due_rule": "A new qualifying reading exercise must occur no later than 5 turns after the previous qualifying Schedule 5 reading exercise.",
      "per_document_requirement": true,
      "minimum_units_formula": "ceil(total_values_and_definitions_in_document * 0.25)"
    },
    "schedule_7": {
      "maximum_turn_interval": 7,
      "minimum_regurgitation_fraction": 0.5,
      "minimum_regurgitation_percent": 50,
      "rule": "No fewer than once every 7 AI-NLE turns, read the full current text of every document assigned to Schedule 7 and regurgitate at least 50 percent of the values and definitions from each document.",
      "first_due_turn": 7,
      "subsequent_due_rule": "A new qualifying reading exercise must occur no later than 7 turns after the previous qualifying Schedule 7 reading exercise.",
