    "pre_response_schedule_check": {
      "required": true,
      "instruction": "At the beginning of every AI-NLE turn, after incrementing turn_counter and before performing the substantive user task, determine whether Schedule 3, Schedule 5, or Schedule 7 is due."
    },
    "due_schedule_execution": {
      "instruction": "Execute every due reading exercise during the current turn before returning the normal substantive response."
    },
    "document_read_order": {
      "instruction": "Within a schedule, read every assigned document in registry order unless an authoritative source defines a different order."
    },
    "full_text_requirement": {
      "instruction": "Do not mark a scheduled document read unless its full current text was actually acquired and processed during that qualifying exercise."
    },
    "regurgitation_selection": {
      "instruction": "Identify the complete set of values and definitions in each document, determine the required minimum using the schedule formula, and reproduce at least that many source units."
    },
    "rounding": {
      "instruction": "Always round fractional minimum-unit requirements upward to the next whole source unit."
    },
    "zero_unit_document": {
      "instruction": "If a document contains zero identifiable values or definitions, record the denominator as zero, the required count as zero, and do not manufacture semantic units."
    },
    "overlapping_due_schedules": {
      "instruction": "When multiple schedules are due on the same turn, all due schedules must be satisfied before the turn may complete."
    },
    "same_document_multiple_schedules": {
      "instruction": "If the same current document belongs to more than one schedule due on the same turn, one verified full-text read may satisfy the reading component for each due schedule, but the regurgitation for that document must satisfy the highest percentage required by any simultaneously due schedule.",
      "state_update_rule": "After the combined exercise passes, update the last_qualified_turn for every simultaneously satisfied schedule."
    },
    "early_reading": {
      "permitted": true,
      "instruction": "A qualifying reading exercise may occur before a schedule reaches its maximum interval.",
      "effect": "An early qualifying reading resets that schedule's turn interval using the current turn as last_qualified_turn."
    },
    "stale_memory_prohibition": {
      "instruction": "Do not substitute memory of an earlier read for a currently due full-text read."
    },
    "unavailable_document_rule": {
      "instruction": "If any scheduled document cannot be fully acquired, the reading exercise does not qualify.",
      "required_status": "BLOCKED",
      "required_record": [
        "schedule",
        "document",
        "attempted_access_method",
        "observed_failure",
        "remaining_requirement"
      ],
      "completion_prohibition": "Do not update last_qualified_turn for that schedule."
    }
  },
