              "source_unit_id": "string",
              "source_type": "value|definition|value_and_definition",
              "source_text": "string",
              "source_locator": "string"
            }
          ],
          "percentage_requirement_satisfied": "boolean"
        }
      ],
      "all_documents_fully_read": "boolean",
      "all_regurgitation_requirements_satisfied": "boolean",
      "qualifying_reading_exercise": "boolean"
    }
  },
  "verification": {
    "schedule_3": {
      "pass_condition": "Every Schedule 3 document was fully read and every document individually met or exceeded its 10 percent regurgitation requirement.",
      "fail_condition": "Any Schedule 3 document was not fully read or any document fell below its 10 percent requirement."
    },
    "schedule_5": {
      "pass_condition": "Every Schedule 5 document was fully read and every document individually met or exceeded its 25 percent regurgitation requirement.",
      "fail_condition": "Any Schedule 5 document was not fully read or any document fell below its 25 percent requirement."
