    "schedule_7": {
      "pass_condition": "Every Schedule 7 document was fully read and every document individually met or exceeded its 50 percent regurgitation requirement.",
      "fail_condition": "Any Schedule 7 document was not fully read or any document fell below its 50 percent requirement."
