    "evidence_rule": "A schedule may be recorded as satisfied only from evidence generated by the current qualifying reading exercise.",
    "self_assertion_rule": "The AI-NLE stating that it remembers, knows, previously read, or understands a document is not evidence of a current qualifying full-text read."
  },
  "failure_handling": {
    "missed_schedule": {
      "condition": "The maximum permitted interval has been reached or exceeded without a qualifying reading exercise.",
      "required_action": "Perform the overdue reading exercise before any discretionary task work and identify the schedule as overdue in the execution record."
    },
    "partial_read": {
      "condition": "One or more scheduled documents were only partially read.",
      "required_action": "Continue acquisition until the complete current text is read or classify the exercise as BLOCKED."
    },
    "insufficient_regurgitation": {
      "condition": "The number of reproduced values and definitions is below the required minimum.",
      "required_action": "Continue the same reading exercise and regurgitate additional qualifying source units until the minimum is reached."
    },
    "incorrect_regurgitation": {
      "condition": "A reproduced unit materially alters the source meaning or operative qualifier.",
      "required_action": "Do not count that unit toward the percentage requirement; replace or correct it from the current source."
    }
  },
  "invariants": [
    "No Schedule 3 interval may exceed 3 governed AI-NLE turns.",
    "No Schedule 5 interval may exceed 5 governed AI-NLE turns.",
    "No Schedule 7 interval may exceed 7 governed AI-NLE turns.",
