              "turns_since_last_qualified_read",
              "due"
            ]
          },
          "schedule_5": {
            "type": "object",
            "required": [
              "last_qualified_turn",
              "turns_since_last_qualified_read",
              "due"
            ]
          },
          "schedule_7": {
            "type": "object",
            "required": [
              "last_qualified_turn",
              "turns_since_last_qualified_read",
              "due"
            ]
          }
        }
      },
      "reading_exercises": {
        "type": "array"
      },
      "substantive_response_authorized": {
        "type": "boolean",
        "description": "True only when every schedule due on the current turn has either completed a qualifying reading exercise or no schedule is due."
      },
      "blocked_reason": {
        "type": [
          "string",
          "null"
        ]
      }
    }
  }
